<script setup lang="ts">
import {restaurantShiftRange} from '../restaurantShifts'
import {computed,onMounted,onBeforeUnmount,ref,watch} from 'vue'
import {usePhasePage} from '../phasePage'
import {useRestSwapText,type RestSwapRequest,type RestSwapPreview} from '../restSwap'
import type {BulkOptions} from '../bulkScheduleTypes'
import {WorkforceApiError} from '../api'
import {addDays,storeToday} from '../time'
import PhaseStatus from './PhaseStatus.vue'
const emit=defineEmits<{close:[];saved:[restDate:string,makeupDate:string]}>(),{api,current,load,write,loading,busy,failure,notice,english}=usePhasePage(),{r}=useRestSwapText()
const dialog=ref<HTMLDialogElement|null>(null),options=ref<BulkOptions>({items:[],total:0,positions:[],shifts:[],timezone:'Asia/Singapore',limit:100,offset:0}),position=ref(''),search=ref(''),selected=ref<string[]>([]),restDate=ref(storeToday()),makeupDate=ref(addDays(storeToday(),5)),shiftId=ref(''),preview=ref<RestSwapPreview|null>(null),offset=ref(0),command=ref<{id:string;request:RestSwapRequest;fingerprint:string}|null>(null)
const locked=computed(()=>busy.value||!!command.value),today=computed(()=>storeToday(options.value.timezone)),last=computed(()=>addDays(today.value,90))
function close(){if(!locked.value)emit('close')}
function refresh(){selected.value=[];preview.value=null;void load(async()=>{const path=(offset:number)=>'/schedule-bulk/options?limit=100&offset='+offset+(position.value?'&positionId='+encodeURIComponent(position.value):'')+'&search='+encodeURIComponent(search.value);const first=await api().get<BulkOptions>(path(0));if(first.total>500)return first;for(let at=100;at<first.total;at+=100){const page=await api().get<BulkOptions>(path(at));if(page.total!==first.total)throw new Error('Employee list changed');first.items.push(...page.items)}return first},result=>{options.value=result;if(result.total>500){failure.value=r('limit');return}selected.value=result.items.map(e=>e.id)})}
function input():RestSwapRequest{return {employeeIds:[...selected.value].sort(),restDate:restDate.value,makeupDate:makeupDate.value,shiftId:shiftId.value}}
watch([restDate,makeupDate,shiftId,selected],()=>{preview.value=null;offset.value=0;notice.value=''}, {deep:true})
function check(){preview.value=null;void load(()=>api().put<RestSwapPreview>('/rest-swaps/preview',input()),result=>{preview.value=result;offset.value=0})}
function submit(){if(!preview.value||!preview.value.ready)return;if(!command.value)command.value={id:crypto.randomUUID(),request:input(),fingerprint:preview.value.fingerprint};const captured=command.value;void write(async()=>{try{await api().put('/rest-swaps/'+captured.id,{request:captured.request,fingerprint:captured.fingerprint});if(current()){command.value=null;emit('saved',captured.request.restDate,captured.request.makeupDate)}}catch(error){if(error instanceof WorkforceApiError&&[400,403,404,409].includes(error.status)){command.value=null;preview.value=null}throw error}})}
onMounted(()=>{dialog.value?.showModal?.();refresh()});onBeforeUnmount(()=>dialog.value?.close?.())
</script>
<template><dialog ref="dialog" class="wf-schedule-dialog wf-bulk-dialog" aria-modal="true" aria-labelledby="wf-rest-swap-title" @cancel.prevent="close"><section class="wf-panel"><header class="wf-toolbar"><h2 id="wf-rest-swap-title">{{r('title')}}</h2><button type="button" :disabled="locked" @click="close">{{r('close')}}</button></header><p class="wf-hint">{{r('hint')}}</p><p class="wf-hint">{{r('rule')}}</p><PhaseStatus :loading="loading" :failure="failure" :notice="notice"/><fieldset :disabled="locked||loading"><form class="wf-filters" @submit.prevent="refresh"><label>{{r('position')}}<select v-model="position"><option value="">{{r('all')}}</option><option v-for="p in options.positions" :key="p.id" :value="p.id">{{p.name}}</option></select></label><label>{{r('search')}}<input v-model="search" type="search" maxlength="100"></label><button>{{r('query')}}</button></form><form @submit.prevent="check"><div class="wf-filters"><label>{{r('rest')}}<input v-model="restDate" type="date" :min="today" :max="last" required></label><label>{{r('makeup')}}<input v-model="makeupDate" type="date" :min="today" :max="last" required></label><label>{{r('shift')}}<select v-model="shiftId" required><option disabled value="">—</option><option v-for="shift in options.shifts.filter(s=>s.enabled)" :key="shift.id" :value="shift.id">{{shift.name}} {{restaurantShiftRange(shift,english())}}</option></select></label></div><div class="wf-filters"><strong>{{r('people')}} · {{r('selected')}} {{selected.length}} / {{options.total}}</strong><button type="button" :disabled="options.total>500" @click="selected=options.items.map(e=>e.id)">{{r('selectAll')}}</button><button type="button" @click="selected=[]">{{r('clear')}}</button></div><div class="wf-transfer-employees"><label v-for="employee in options.items" :key="employee.id" class="wf-check"><input v-model="selected" type="checkbox" :value="employee.id">{{employee.name}} <small>{{employee.employeeNo}}</small></label><p v-if="!options.items.length">{{r('empty')}}</p></div><footer class="wf-form-actions"><button class="primary" :disabled="!selected.length||!shiftId||options.total>500">{{r('preview')}}</button></footer></form></fieldset><section v-if="preview"><div class="wf-filters"><strong>{{r('ready')}} {{preview.ready}}</strong><span>{{r('conflict')}} {{preview.conflicts}}</span><span>{{r('cancelCount')}} {{preview.cancellations}}</span></div><div class="wf-table-wrap"><table><thead><tr><th>{{r('people')}}</th><th>{{r('cancelCount')}}</th><th>{{r('reason')}}</th></tr></thead><tbody><tr v-for="row in preview.items.slice(offset,offset+50)" :key="row.employeeId"><td>{{row.employeeName}} {{row.employeeNo}}</td><td>{{row.cancelSchedules.length}}</td><td>{{row.status==='ready'?r('ready'):r(row.reason as 'IN_USE')}}</td></tr></tbody></table></div><footer class="wf-pagination"><button :disabled="locked||offset===0" @click="offset-=50">←</button><button :disabled="locked||offset+50>=preview.items.length" @click="offset+=50">→</button></footer><p v-if="command" class="wf-hint">{{r('retry')}}</p><footer class="wf-form-actions"><button class="primary" :disabled="busy||!preview.ready" @click="submit">{{r('save')}} · {{preview.ready}}</button></footer></section></section></dialog></template>
<style scoped>.wf-transfer-employees{display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:8px;max-height:240px;overflow:auto}.wf-transfer-employees .wf-check{display:flex;gap:5px;align-items:center}</style>

